function profitBlock(profits, minLen, maxLen) {
  let best = -Infinity;
  for (let start = 0; start < profits.length; start++) {
    let sum = 0;
    for (let length = 1; length <= maxLen && start + length <= profits.length; length++) {
      sum += profits[start + length - 1];
      if (length >= minLen && sum > best) best = sum;
    }
  }
  return best;
}

function profitBlock(profits, minLen, maxLen) {
  const n = profits.length;
  const prefix = new Int32Array(n + 1);
  for (let i = 0; i < n; i++) prefix[i + 1] = prefix[i] + profits[i];
  const levels = [prefix];
  for (let span = 1; span * 2 <= n + 1; span *= 2) {
    const previous = levels[levels.length - 1];
    const next = new Int32Array(n + 1);
    for (let i = 0; i + span * 2 <= n + 1; i++) next[i] = Math.min(previous[i], previous[i + span]);
    levels.push(next);
  }
  const cheapest = (low, high) => {
    const k = 31 - Math.clz32(high - low + 1);
    return Math.min(levels[k][low], levels[k][high - (1 << k) + 1]);
  };
  let best = -Infinity;
  for (let end = minLen; end <= n; end++) {
    const total = prefix[end] - cheapest(Math.max(0, end - maxLen), end - minLen);
    if (total > best) best = total;
  }
  return best;
}

function profitBlock(profits, minLen, maxLen) {
  const n = profits.length;
  const prefix = new Int32Array(n + 1);
  for (let i = 0; i < n; i++) prefix[i + 1] = prefix[i] + profits[i];
  const deque = new Int32Array(n + 1);
  let head = 0;
  let tail = 0;
  let best = -Infinity;
  for (let end = minLen; end <= n; end++) {
    const entering = end - minLen;
    while (tail > head && prefix[deque[tail - 1]] >= prefix[entering]) tail--;
    deque[tail++] = entering;
    while (deque[head] < end - maxLen) head++;
    const total = prefix[end] - prefix[deque[head]];
    if (total > best) best = total;
  }
  return best;
}
